const ROTARY_MONTHS = [
  "July", "August", "September", "October", "November", "December",
  "January", "February", "March", "April", "May", "June",
];

function rotaryYearOf(date) {
  const y = date.getFullYear();
  const m = date.getMonth() + 1; // 1-12
  return m >= 7 ? `${y}-${String((y + 1) % 100).padStart(2, "0")}` : `${y - 1}-${String(y % 100).padStart(2, "0")}`;
}

function yearList(current) {
  const startYear = parseInt(current.slice(0, 4), 10);
  const years = [];
  for (let y = startYear - 6; y <= startYear + 2; y++) {
    years.push(`${y}-${String((y + 1) % 100).padStart(2, "0")}`);
  }
  return years;
}

function monthFromDateStr(dateStr) {
  if (!dateStr) return "";
  const d = new Date(dateStr + "T00:00:00");
  return ROTARY_MONTHS[(d.getMonth() + 12 - 6) % 12] || d.toLocaleString("en-US", { month: "long" });
}
// simpler & correct: just use actual month name
function monthName(dateStr) {
  if (!dateStr) return "";
  const d = new Date(dateStr + "T00:00:00");
  return d.toLocaleString("en-US", { month: "long" });
}

const CURRENT_YEAR = rotaryYearOf(new Date());
const money = (n) =>
  "₹" + (Number(n) || 0).toLocaleString("en-IN", { maximumFractionDigits: 0 });

const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36);

/* ---------------------------------------------------------------
   Persistence — shared repository, visible to the whole club.
------------------------------------------------------------------ */
const STORAGE_KEY = "rotary-projects-v1";

async function loadProjects() {
  try {
    const res = await window.storage.get(STORAGE_KEY, true);
    return res ? JSON.parse(res.value) : [];
  } catch {
    return [];
  }
}
async function saveProjects(list) {
  try {
    await window.storage.set(STORAGE_KEY, JSON.stringify(list), true);
  } catch (e) {
    console.error("Storage error", e);
  }
}

/* ---------------------------------------------------------------
   Small gear-wheel signature mark (Rotary motif, used sparingly)
------------------------------------------------------------------ */
function GearMark({ size = 28, color = COLORS.gold }) {
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" fill="none">
      <g fill={color}>
        {Array.from({ length: 12 }).map((_, i) => {
          const angle = (i * 30 * Math.PI) / 180;
          const x1 = 24 + 17 * Math.cos(angle);
          const y1 = 24 + 17 * Math.sin(angle);
          const x2 = 24 + 22 * Math.cos(angle);
          const y2 = 24 + 22 * Math.sin(angle);
          return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth="4" />;
        })}
        <circle cx="24" cy="24" r="14" fill={COLORS.blue} />
        <circle cx="24" cy="24" r="5.5" fill={color} />
      </g>
    </svg>
  );
}

