/* ---------------------------------------------------------------
   Rich-text description editor (contentEditable + execCommand)
------------------------------------------------------------------ */
function RichTextEditor({ value, onChange }) {
  const ref = useRef(null);
  const [fontFamily, setFontFamily] = useState("Inter");

  useEffect(() => {
    if (ref.current && ref.current.innerHTML !== value) {
      ref.current.innerHTML = value || "";
    }
    // eslint-disable-next-line
  }, []);

  const cmd = (command, arg) => {
    ref.current?.focus();
    document.execCommand(command, false, arg);
    onChange(ref.current.innerHTML);
  };

  const btnStyle = {
    display: "flex", alignItems: "center", justifyContent: "center",
    width: 30, height: 30, borderRadius: 6, border: `1px solid ${COLORS.line}`,
    background: COLORS.white, cursor: "pointer", color: COLORS.ink,
  };

  return (
    <div style={{ border: `1px solid ${COLORS.line}`, borderRadius: 10, overflow: "hidden" }}>
      <div style={{
        display: "flex", gap: 6, alignItems: "center", padding: 8,
        background: COLORS.cream, borderBottom: `1px solid ${COLORS.line}`, flexWrap: "wrap",
      }}>
        <button type="button" style={btnStyle} onClick={() => cmd("bold")}><Bold size={14} /></button>
        <button type="button" style={btnStyle} onClick={() => cmd("italic")}><Italic size={14} /></button>
        <button type="button" style={btnStyle} onClick={() => cmd("underline")}><Underline size={14} /></button>
        <button type="button" style={{ ...btnStyle, width: "auto", padding: "0 8px", fontSize: 12 }}
          onClick={() => cmd("insertUnorderedList")}>• List</button>
        <select
          value={fontFamily}
          onChange={(e) => { setFontFamily(e.target.value); cmd("fontName", e.target.value); }}
          style={{ fontSize: 12, padding: "4px 6px", borderRadius: 6, border: `1px solid ${COLORS.line}` }}
        >
          <option>Inter</option>
          <option>Lora</option>
          <option>Georgia</option>
          <option>Courier New</option>
        </select>
        <select
          onChange={(e) => cmd("fontSize", e.target.value)}
          defaultValue="3"
          style={{ fontSize: 12, padding: "4px 6px", borderRadius: 6, border: `1px solid ${COLORS.line}` }}
        >
          <option value="2">Small</option>
          <option value="3">Normal</option>
          <option value="5">Large</option>
          <option value="7">XL</option>
        </select>
      </div>
      <div
        ref={ref}
        contentEditable
        onInput={(e) => onChange(e.currentTarget.innerHTML)}
        style={{
          minHeight: 120, padding: 12, fontFamily: "Inter, sans-serif",
          fontSize: 14, color: COLORS.ink, outline: "none", lineHeight: 1.6,
        }}
        data-placeholder="Describe the project — impact, beneficiaries, partners..."
      />
    </div>
  );
}

