const MAX_FILE_BYTES = 1_500_000;

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    if (file.size > MAX_FILE_BYTES) {
      reject(new Error(`"${file.name}" is too large (max ~1.5MB per file in this demo repository). Use a video/audio link instead for larger media.`));
      return;
    }
    const reader = new FileReader();
    reader.onload = () => resolve({ name: file.name, dataUrl: reader.result });
    reader.onerror = () => reject(new Error("Could not read file."));
    reader.readAsDataURL(file);
  });
}

/* ---------------------------------------------------------------
   useClickOutside — shared helper for dropdown popups
------------------------------------------------------------------ */
function useClickOutside(ref, onOutside) {
  useEffect(() => {
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) onOutside();
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [ref, onOutside]);
}

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function pad2(n) { return String(n).padStart(2, "0"); }
function toDateValue(y, m, d) { return `${y}-${pad2(m + 1)}-${pad2(d)}`; }
function formatDisplayDate(value) {
  if (!value) return "";
  const d = new Date(value + "T00:00:00");
  return `${d.getDate()} ${MONTH_NAMES[d.getMonth()].slice(0, 3)} ${d.getFullYear()}`;
}

/* Dropdown calendar date picker — input field + popup calendar, per UX
   guidance favoring a compact calendar over free typing or triple dropdowns. */
function DatePicker({ value, onChange, placeholder = "Select date" }) {
  const [open, setOpen] = useState(false);
  const seed = value ? new Date(value + "T00:00:00") : new Date();
  const [viewY, setViewY] = useState(seed.getFullYear());
  const [viewM, setViewM] = useState(seed.getMonth());
  const ref = useRef(null);
  useClickOutside(ref, () => setOpen(false));

  const firstDow = new Date(viewY, viewM, 1).getDay();
  const daysInMonth = new Date(viewY, viewM + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < firstDow; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const selectDay = (d) => {
    onChange(toDateValue(viewY, viewM, d));
    setOpen(false);
  };
  const isSelected = (d) => value === toDateValue(viewY, viewM, d);
  const isToday = (d) => {
    const t = new Date();
    return t.getFullYear() === viewY && t.getMonth() === viewM && t.getDate() === d;
  };

  const navMonth = (delta) => {
    let m = viewM + delta, y = viewY;
    if (m < 0) { m = 11; y -= 1; } else if (m > 11) { m = 0; y += 1; }
    setViewM(m); setViewY(y);
  };

  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button type="button" onClick={() => setOpen((o) => !o)} style={{
        width: "100%", textAlign: "left", padding: "9px 11px", borderRadius: 8,
        border: `1px solid ${COLORS.line}`, background: COLORS.white, cursor: "pointer",
        fontFamily: "Inter, sans-serif", fontSize: 13.5, color: value ? COLORS.ink : "#9AA3B5",
        display: "flex", alignItems: "center", justifyContent: "space-between",
      }}>
        {value ? formatDisplayDate(value) : placeholder}
        <span style={{ fontSize: 13 }}>📅</span>
      </button>

      {open && (
        <div style={{
          position: "absolute", top: "calc(100% + 6px)", left: 0, zIndex: 30,
          background: COLORS.white, border: `1px solid ${COLORS.line}`, borderRadius: 12,
          boxShadow: "0 14px 32px rgba(8,42,80,.18)", padding: 12, width: 258,
        }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
            <button type="button" onClick={() => navMonth(-1)} style={navBtn}>‹</button>
            <div style={{ fontFamily: "Inter, sans-serif", fontWeight: 700, fontSize: 13, color: COLORS.blueDeep }}>
              {MONTH_NAMES[viewM]} {viewY}
            </div>
            <button type="button" onClick={() => navMonth(1)} style={navBtn}>›</button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 2, marginBottom: 4 }}>
            {WEEKDAYS.map((w) => (
              <div key={w} style={{ textAlign: "center", fontSize: 10.5, color: COLORS.inkSoft, fontWeight: 700, padding: "4px 0" }}>{w}</div>
            ))}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 2 }}>
            {cells.map((d, i) => d === null ? <div key={i} /> : (
              <button key={i} type="button" onClick={() => selectDay(d)} style={{
                width: 30, height: 30, borderRadius: 8, border: "none", cursor: "pointer",
                fontFamily: "Inter, sans-serif", fontSize: 12.5,
                background: isSelected(d) ? COLORS.blue : isToday(d) ? COLORS.goldSoft : "transparent",
                color: isSelected(d) ? COLORS.white : COLORS.ink,
                fontWeight: isSelected(d) || isToday(d) ? 700 : 500,
              }}>{d}</button>
            ))}
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", marginTop: 10, borderTop: `1px solid ${COLORS.line}`, paddingTop: 8 }}>
            <button type="button" onClick={() => { const t = new Date(); setViewY(t.getFullYear()); setViewM(t.getMonth()); onChange(toDateValue(t.getFullYear(), t.getMonth(), t.getDate())); setOpen(false); }}
              style={{ background: "none", border: "none", color: COLORS.blue, fontFamily: "Inter, sans-serif", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>Today</button>
            {value && (
              <button type="button" onClick={() => { onChange(""); setOpen(false); }}
                style={{ background: "none", border: "none", color: COLORS.inkSoft, fontFamily: "Inter, sans-serif", fontSize: 12, cursor: "pointer" }}>Clear</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
const navBtn = {
  width: 26, height: 26, borderRadius: 999, border: `1px solid ${COLORS.line}`,
  background: COLORS.white, cursor: "pointer", fontSize: 15, color: COLORS.blue, lineHeight: 1,
};

/* Dropdown time picker — tap/scroll hour, minute (5-min steps) & AM/PM lists,
   which is the recommended pattern for quick, error-free time entry. */
function TimePicker({ value, onChange, placeholder = "Select time" }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useClickOutside(ref, () => setOpen(false));

  let h24 = 9, min = 0;
  if (value) { const [hh, mm] = value.split(":").map(Number); h24 = hh; min = mm; }
  const period = h24 >= 12 ? "PM" : "AM";
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;

  const commit = (nh12, nmin, nperiod) => {
    let hh = nh12 % 12;
    if (nperiod === "PM") hh += 12;
    onChange(`${pad2(hh)}:${pad2(nmin)}`);
  };

  const hours = Array.from({ length: 12 }, (_, i) => i + 1);
  const minutes = Array.from({ length: 12 }, (_, i) => i * 5);

  const display = value ? `${pad2(h12)}:${pad2(min)} ${period}` : placeholder;

  const col = { maxHeight: 160, overflowY: "auto", display: "flex", flexDirection: "column", gap: 2, padding: "0 3px" };
  const optBtn = (active) => ({
    padding: "6px 10px", borderRadius: 7, border: "none", cursor: "pointer",
    fontFamily: "Inter, sans-serif", fontSize: 12.5, textAlign: "center",
    background: active ? COLORS.blue : "transparent", color: active ? COLORS.white : COLORS.ink,
    fontWeight: active ? 700 : 500,
  });

  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button type="button" onClick={() => setOpen((o) => !o)} style={{
        width: "100%", textAlign: "left", padding: "9px 11px", borderRadius: 8,
        border: `1px solid ${COLORS.line}`, background: COLORS.white, cursor: "pointer",
        fontFamily: "Inter, sans-serif", fontSize: 13.5, color: value ? COLORS.ink : "#9AA3B5",
        display: "flex", alignItems: "center", justifyContent: "space-between",
      }}>
        {display}
        <span style={{ fontSize: 13 }}>🕒</span>
      </button>

      {open && (
        <div style={{
          position: "absolute", top: "calc(100% + 6px)", left: 0, zIndex: 30,
          background: COLORS.white, border: `1px solid ${COLORS.line}`, borderRadius: 12,
          boxShadow: "0 14px 32px rgba(8,42,80,.18)", padding: 10, display: "flex", gap: 6, width: 210,
        }}>
          <div style={col}>
            {hours.map((h) => (
              <button key={h} type="button" style={optBtn(h === h12)} onClick={() => commit(h, min, period)}>{pad2(h)}</button>
            ))}
          </div>
          <div style={col}>
            {minutes.map((m) => (
              <button key={m} type="button" style={optBtn(m === min)} onClick={() => commit(h12, m, period)}>{pad2(m)}</button>
            ))}
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            {["AM", "PM"].map((p) => (
              <button key={p} type="button" style={optBtn(p === period)} onClick={() => commit(h12, min, p)}>{p}</button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function ProjectForm({ role, lockedAvenue, initial, onCancel, onSave }) {
  const isEdit = !!initial;
  const [form, setForm] = useState(initial || {
    id: uid(),
    year: CURRENT_YEAR,
    startDate: "",
    endDate: "",
    startTime: "",
    endTime: "",
    name: "",
    avenue: lockedAvenue || AVENUES[0],
    volunteerHours: "",
    contributionCash: "",
    contributionKind: "",
    description: "",
    media: { images: [], files: [], music: [], videoLinks: [] },
  });
  const [videoInput, setVideoInput] = useState("");
  const [error, setError] = useState("");

  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const handleUpload = async (e, kind) => {
    const files = Array.from(e.target.files || []);
    try {
      const items = await Promise.all(files.map(fileToDataUrl));
      setForm((f) => ({ ...f, media: { ...f.media, [kind]: [...f.media[kind], ...items] } }));
    } catch (err) {
      setError(err.message);
    }
    e.target.value = "";
  };

  const removeMedia = (kind, idx) => {
    setForm((f) => ({
      ...f,
      media: { ...f.media, [kind]: f.media[kind].filter((_, i) => i !== idx) },
    }));
  };

  const addVideoLink = () => {
    if (!videoInput.trim()) return;
    setForm((f) => ({ ...f, media: { ...f.media, videoLinks: [...f.media.videoLinks, videoInput.trim()] } }));
    setVideoInput("");
  };

  const submit = () => {
    if (!form.year || !form.startDate || !form.endDate || !form.startTime || !form.endTime || !form.name.trim() || !form.avenue) {
      setError("Please fill in all required fields: year, start/end date, start/end time, project name and avenue.");
      return;
    }
    if (role === "director" && form.avenue !== lockedAvenue) {
      setError("Avenue directors can only add projects to their own avenue.");
      return;
    }
    onSave({ ...form, month: monthName(form.startDate) });
  };

  const inputStyle = {
    width: "100%", padding: "9px 11px", borderRadius: 8,
    border: `1px solid ${COLORS.line}`, fontFamily: "Inter, sans-serif",
    fontSize: 13.5, color: COLORS.ink, background: COLORS.white,
  };
  const label = { fontSize: 11.5, fontWeight: 700, color: COLORS.inkSoft, letterSpacing: ".03em", textTransform: "uppercase", marginBottom: 5, display: "block" };
  const field = { marginBottom: 14 };

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(8,42,80,.55)", zIndex: 50,
      display: "flex", alignItems: "center", justifyContent: "center", padding: 16,
    }}>
      <div style={{
        background: COLORS.white, borderRadius: 16, width: "100%", maxWidth: 720,
        maxHeight: "92vh", overflowY: "auto", boxShadow: "0 30px 60px rgba(8,42,80,.35)",
      }}>
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "18px 22px", borderBottom: `1px solid ${COLORS.line}`,
          position: "sticky", top: 0, background: COLORS.white, zIndex: 2,
        }}>
          <h2 style={{ fontFamily: "Lora, serif", fontSize: 19, color: COLORS.blue, margin: 0 }}>
            {isEdit ? "Edit Project" : "Add New Project"}
          </h2>
          <button onClick={onCancel} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.inkSoft }}>
            <X size={20} />
          </button>
        </div>

        <div style={{ padding: 22 }}>
          {error && (
            <div style={{ background: "#FDEBEC", color: COLORS.cranberry, padding: "9px 12px", borderRadius: 8, fontSize: 12.5, marginBottom: 14, fontFamily: "Inter, sans-serif" }}>
              {error}
            </div>
          )}

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
            <div style={field}>
              <label style={label}>Rotary Year *</label>
              <select style={inputStyle} value={form.year} disabled={role === "director"}
                onChange={(e) => set("year", e.target.value)}>
                {yearList(CURRENT_YEAR).map((y) => <option key={y} value={y}>{y}</option>)}
              </select>
            </div>
            <div style={field}>
              <label style={label}>Avenue *</label>
              <select style={inputStyle} value={form.avenue} disabled={role === "director"}
                onChange={(e) => set("avenue", e.target.value)}>
                {AVENUES.map((a) => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
            <div style={{ ...field, position: "relative" }}>
              <label style={label}>Start Date *</label>
              <DatePicker value={form.startDate} onChange={(v) => set("startDate", v)} />
            </div>
            <div style={{ ...field, position: "relative" }}>
              <label style={label}>End Date *</label>
              <DatePicker value={form.endDate} onChange={(v) => set("endDate", v)} />
            </div>
            <div style={{ ...field, position: "relative" }}>
              <label style={label}>Start Time *</label>
              <TimePicker value={form.startTime} onChange={(v) => set("startTime", v)} />
            </div>
            <div style={{ ...field, position: "relative" }}>
              <label style={label}>End Time *</label>
              <TimePicker value={form.endTime} onChange={(v) => set("endTime", v)} />
            </div>
            <div style={{ ...field, gridColumn: "1 / -1" }}>
              <label style={label}>Project Name *</label>
              <input style={inputStyle} value={form.name} placeholder="e.g. Free Heart Surgery Camp"
                onChange={(e) => set("name", e.target.value)} />
            </div>
            {form.startDate && (
              <div style={{ gridColumn: "1 / -1", fontSize: 12, color: COLORS.inkSoft, marginTop: -8, marginBottom: 6, fontFamily: "Inter, sans-serif" }}>
                Month (auto-derived from start date): <strong>{monthName(form.startDate)}</strong>
              </div>
            )}
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 14, marginTop: 4 }}>
            <div style={field}>
              <label style={label}>Volunteer Hours</label>
              <input type="number" min="0" style={inputStyle} value={form.volunteerHours}
                onChange={(e) => set("volunteerHours", e.target.value)} placeholder="Optional" />
            </div>
            <div style={field}>
              <label style={label}>Contribution — Cash (₹)</label>
              <input type="number" min="0" style={inputStyle} value={form.contributionCash}
                onChange={(e) => set("contributionCash", e.target.value)} placeholder="Optional" />
            </div>
            <div style={field}>
              <label style={label}>Contribution — In Kind (₹)</label>
              <input type="number" min="0" style={inputStyle} value={form.contributionKind}
                onChange={(e) => set("contributionKind", e.target.value)} placeholder="Optional" />
            </div>
          </div>

          <div style={field}>
            <label style={label}>Project Description</label>
            <RichTextEditor value={form.description} onChange={(html) => set("description", html)} />
          </div>

          <div style={field}>
            <label style={label}>Media (all optional)</label>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <UploadBox icon={ImageIcon} text="Upload image(s)" accept="image/*" multiple
                onChange={(e) => handleUpload(e, "images")} />
              <UploadBox icon={Paperclip} text="Upload file(s)" accept="*" multiple
                onChange={(e) => handleUpload(e, "files")} />
              <UploadBox icon={Music} text="Upload music" accept="audio/*" multiple
                onChange={(e) => handleUpload(e, "music")} />
              <div style={{ display: "flex", gap: 6 }}>
                <input style={inputStyle} placeholder="Paste video link (YouTube etc.)"
                  value={videoInput} onChange={(e) => setVideoInput(e.target.value)} />
                <button type="button" onClick={addVideoLink} style={{
                  border: "none", borderRadius: 8, background: COLORS.blue, color: COLORS.white,
                  padding: "0 12px", cursor: "pointer",
                }}><LinkIcon size={14} /></button>
              </div>
            </div>

            <MediaChips form={form} removeMedia={removeMedia} />
          </div>

          <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 8 }}>
            <button onClick={onCancel} style={{
              padding: "10px 18px", borderRadius: 999, border: `1px solid ${COLORS.line}`,
              background: "white", color: COLORS.inkSoft, cursor: "pointer", fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 13,
            }}>Cancel</button>
            <button onClick={submit} style={{
              padding: "10px 20px", borderRadius: 999, border: "none",
              background: COLORS.gold, color: COLORS.blueDeep, cursor: "pointer",
              fontFamily: "Inter, sans-serif", fontWeight: 700, fontSize: 13,
            }}>{isEdit ? "Save Changes" : "Add Project"}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

function UploadBox({ icon: Icon, text, accept, multiple, onChange }) {
  return (
    <label style={{
      display: "flex", alignItems: "center", gap: 8, padding: "10px 12px",
      border: `1.5px dashed ${COLORS.line}`, borderRadius: 8, cursor: "pointer",
      fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, background: COLORS.cream,
    }}>
      <Icon size={15} color={COLORS.blue} /> {text}
      <input type="file" accept={accept} multiple={multiple} onChange={onChange} style={{ display: "none" }} />
    </label>
  );
}

function MediaChips({ form, removeMedia }) {
  const chip = { display: "flex", alignItems: "center", gap: 6, background: COLORS.blueSoft, padding: "5px 9px", borderRadius: 999, fontSize: 11.5, fontFamily: "Inter, sans-serif", color: COLORS.blue };
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 10 }}>
      {form.media.images.map((f, i) => (
        <span key={i} style={chip}><ImageIcon size={12} />{f.name}<X size={12} style={{ cursor: "pointer" }} onClick={() => removeMedia("images", i)} /></span>
      ))}
      {form.media.files.map((f, i) => (
        <span key={i} style={chip}><Paperclip size={12} />{f.name}<X size={12} style={{ cursor: "pointer" }} onClick={() => removeMedia("files", i)} /></span>
      ))}
      {form.media.music.map((f, i) => (
        <span key={i} style={chip}><Music size={12} />{f.name}<X size={12} style={{ cursor: "pointer" }} onClick={() => removeMedia("music", i)} /></span>
      ))}
      {form.media.videoLinks.map((f, i) => (
        <span key={i} style={chip}><LinkIcon size={12} />{f.length > 26 ? f.slice(0, 26) + "…" : f}<X size={12} style={{ cursor: "pointer" }} onClick={() => removeMedia("videoLinks", i)} /></span>
      ))}
    </div>
  );
}

/* ---------------------------------------------------------------
   Project detail drawer
------------------------------------------------------------------ */
function ProjectDetail({ project, onClose }) {
  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(8,42,80,.5)", zIndex: 50,
      display: "flex", justifyContent: "flex-end",
    }}>
      <div style={{ width: "min(520px, 100%)", background: COLORS.white, height: "100%", overflowY: "auto", boxShadow: "-20px 0 40px rgba(8,42,80,.25)" }}>
        <div style={{ padding: "20px 24px", borderBottom: `1px solid ${COLORS.line}`, position: "sticky", top: 0, background: COLORS.white, display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div>
            <span style={{
              fontSize: 11, fontWeight: 700, color: AVENUE_COLORS[project.avenue], background: `${AVENUE_COLORS[project.avenue]}18`,
              padding: "3px 9px", borderRadius: 999, fontFamily: "Inter, sans-serif",
            }}>{project.avenue}</span>
            <h2 style={{ fontFamily: "Lora, serif", fontSize: 22, color: COLORS.blueDeep, margin: "8px 0 0" }}>{project.name}</h2>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, margin: "4px 0 0" }}>
              {project.year} · {project.month} · {project.startDate} → {project.endDate} · {project.startTime}–{project.endTime}
            </p>
          </div>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.inkSoft }}><X size={20} /></button>
        </div>

        <div style={{ padding: 24 }}>
          <div style={{ display: "flex", gap: 10, marginBottom: 18, flexWrap: "wrap" }}>
            {project.volunteerHours ? <Stat icon={Clock} label="Volunteer Hrs" value={project.volunteerHours} /> : null}
            {project.contributionCash ? <Stat icon={IndianRupee} label="Cash" value={money(project.contributionCash)} /> : null}
            {project.contributionKind ? <Stat icon={Gift} label="In Kind" value={money(project.contributionKind)} /> : null}
          </div>

          {project.description && (
            <div
              style={{ fontFamily: "Inter, sans-serif", fontSize: 14, color: COLORS.ink, lineHeight: 1.7, marginBottom: 20 }}
              dangerouslySetInnerHTML={{ __html: project.description }}
            />
          )}

          {project.media?.images?.length > 0 && (
            <MediaSection title="Images">
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                {project.media.images.map((f, i) => (
                  <img key={i} src={f.dataUrl} alt={f.name} style={{ width: "100%", borderRadius: 8, border: `1px solid ${COLORS.line}` }} />
                ))}
              </div>
            </MediaSection>
          )}

          {project.media?.music?.length > 0 && (
            <MediaSection title="Music">
              {project.media.music.map((f, i) => (
                <audio key={i} controls src={f.dataUrl} style={{ width: "100%", marginBottom: 8 }} />
              ))}
            </MediaSection>
          )}

          {project.media?.files?.length > 0 && (
            <MediaSection title="Files">
              {project.media.files.map((f, i) => (
                <a key={i} href={f.dataUrl} download={f.name} style={{ display: "flex", alignItems: "center", gap: 8, fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.blue, marginBottom: 6, textDecoration: "none" }}>
                  <Paperclip size={14} /> {f.name}
                </a>
              ))}
            </MediaSection>
          )}

          {project.media?.videoLinks?.length > 0 && (
            <MediaSection title="Video Links">
              {project.media.videoLinks.map((v, i) => (
                <a key={i} href={v} target="_blank" rel="noreferrer" style={{ display: "flex", alignItems: "center", gap: 8, fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.blue, marginBottom: 6, textDecoration: "none", wordBreak: "break-all" }}>
                  <LinkIcon size={14} /> {v}
                </a>
              ))}
            </MediaSection>
          )}
        </div>
      </div>
    </div>
  );
}

function MediaSection({ title, children }) {
  return (
    <div style={{ marginBottom: 20 }}>
      <h4 style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, fontWeight: 700, color: COLORS.inkSoft, textTransform: "uppercase", letterSpacing: ".04em", marginBottom: 8 }}>{title}</h4>
      {children}
    </div>
  );
}

function Stat({ icon: Icon, label, value }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, background: COLORS.blueSoft, padding: "8px 12px", borderRadius: 10 }}>
      <Icon size={15} color={COLORS.blue} />
      <div>
        <div style={{ fontFamily: "Inter, sans-serif", fontSize: 10.5, color: COLORS.inkSoft, fontWeight: 600 }}>{label}</div>
        <div style={{ fontFamily: "Lora, serif", fontSize: 14, color: COLORS.blueDeep, fontWeight: 600 }}>{value}</div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   Project card
------------------------------------------------------------------ */
function ProjectCard({ p, canManage, onOpen, onEdit, onDelete }) {
  return (
    <div
      onClick={() => onOpen(p)}
      style={{
        background: COLORS.white, border: `1px solid ${COLORS.line}`, borderRadius: 14,
        padding: 16, cursor: "pointer", position: "relative", transition: "box-shadow .15s, transform .15s",
      }}
      onMouseEnter={(e) => { e.currentTarget.style.boxShadow = "0 10px 24px rgba(12,58,110,.12)"; e.currentTarget.style.transform = "translateY(-2px)"; }}
      onMouseLeave={(e) => { e.currentTarget.style.boxShadow = "none"; e.currentTarget.style.transform = "none"; }}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
        <span style={{
          fontSize: 10.5, fontWeight: 700, color: AVENUE_COLORS[p.avenue], background: `${AVENUE_COLORS[p.avenue]}18`,
          padding: "3px 9px", borderRadius: 999, fontFamily: "Inter, sans-serif",
        }}>{p.avenue}</span>
        {canManage && (
          <div style={{ display: "flex", gap: 6 }} onClick={(e) => e.stopPropagation()}>
            <button onClick={() => onEdit(p)} style={{ border: "none", background: "none", cursor: "pointer", color: COLORS.inkSoft }}><Pencil size={14} /></button>
            <button onClick={() => onDelete(p)} style={{ border: "none", background: "none", cursor: "pointer", color: COLORS.cranberry }}><Trash2 size={14} /></button>
          </div>
        )}
      </div>
      <h3 style={{ fontFamily: "Lora, serif", fontSize: 16.5, color: COLORS.blueDeep, margin: "0 0 6px" }}>{p.name}</h3>
      <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.inkSoft, margin: "0 0 12px" }}>
        {p.month} {p.year} · {p.startDate} → {p.endDate}
      </p>
      <div style={{ display: "flex", gap: 14, fontFamily: "Inter, sans-serif", fontSize: 11.5, color: COLORS.inkSoft }}>
        {p.volunteerHours ? <span><Clock size={11} style={{ verticalAlign: -1 }} /> {p.volunteerHours}h</span> : null}
        {p.contributionCash ? <span><IndianRupee size={11} style={{ verticalAlign: -1 }} /> {money(p.contributionCash)}</span> : null}
        {p.contributionKind ? <span><Gift size={11} style={{ verticalAlign: -1 }} /> {money(p.contributionKind)}</span> : null}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   Main App
------------------------------------------------------------------ */
export default function App() {
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [role, setRole] = useState("admin");
  const [director, setDirector] = useState(AVENUES[0]);

  const [filterYear, setFilterYear] = useState(CURRENT_YEAR);
  const [filterMonth, setFilterMonth] = useState("All");
  const [filterAvenue, setFilterAvenue] = useState("All");

  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [viewing, setViewing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  useEffect(() => {
    (async () => {
      const list = await loadProjects();
      setProjects(list);
      setLoading(false);
    })();
  }, []);

  const persist = useCallback(async (next) => {
    setProjects(next);
    await saveProjects(next);
  }, []);

  const canManage = (p) => {
    if (role === "admin") return p.year === CURRENT_YEAR; // past years: dev-only via code
    return false;
  };
  const canAdd = role === "admin" || role === "director";

  const handleSave = async (proj) => {
    const exists = projects.some((p) => p.id === proj.id);
    const next = exists ? projects.map((p) => (p.id === proj.id ? proj : p)) : [proj, ...projects];
    await persist(next);
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (p) => {
    await persist(projects.filter((x) => x.id !== p.id));
    setConfirmDelete(null);
  };

  const years = useMemo(() => yearList(CURRENT_YEAR), []);
  const projectsInYear = useMemo(() => projects.filter((p) => filterYear === "All" || p.year === filterYear), [projects, filterYear]);
  const monthsAvailable = useMemo(() => {
    const set = new Set(projectsInYear.map((p) => p.month));
    return ROTARY_MONTHS.filter((m) => set.has(m));
  }, [projectsInYear]);

  const filtered = useMemo(() => projectsInYear.filter((p) =>
    (filterMonth === "All" || p.month === filterMonth) &&
    (filterAvenue === "All" || p.avenue === filterAvenue)
  ), [projectsInYear, filterMonth, filterAvenue]);

  const totals = useMemo(() => filtered.reduce((acc, p) => ({
    hours: acc.hours + (Number(p.volunteerHours) || 0),
    cash: acc.cash + (Number(p.contributionCash) || 0),
    kind: acc.kind + (Number(p.contributionKind) || 0),
    count: acc.count + 1,
  }), { hours: 0, cash: 0, kind: 0, count: 0 }), [filtered]);

  const avenueChartData = useMemo(() => AVENUES.map((a) => ({
    avenue: a.replace(" Service", ""),
    projects: filtered.filter((p) => p.avenue === a).length,
  })), [filtered]);

  const monthChartData = useMemo(() => ROTARY_MONTHS.map((m) => {
    const rows = projectsInYear.filter((p) => p.month === m && (filterAvenue === "All" || p.avenue === filterAvenue));
    return {
      month: m.slice(0, 3),
      Cash: rows.reduce((s, p) => s + (Number(p.contributionCash) || 0), 0),
      "In Kind": rows.reduce((s, p) => s + (Number(p.contributionKind) || 0), 0),
    };
  }), [projectsInYear, filterAvenue]);

  const openAdd = () => { setEditing(null); setShowForm(true); };
  const openEdit = (p) => { setEditing(p); setShowForm(true); };

  return (
    <div style={{ background: COLORS.cream, minHeight: "100%", fontFamily: "Inter, sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,500;0,600;0,700;1,500&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        [contenteditable]:empty:before { content: attr(data-placeholder); color: #A9AFBB; }
      `}</style>

      {/* Header */}
      <div style={{ background: `linear-gradient(135deg, ${COLORS.blue}, ${COLORS.blueDeep})`, padding: "26px 28px", position: "relative", overflow: "hidden" }}>
        <div style={{ position: "absolute", right: -30, top: -30, opacity: 0.15 }}>
          <GearMark size={220} color="#FFFFFF" />
        </div>
        <div style={{ position: "relative", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            <div style={{ background: COLORS.white, borderRadius: 10, padding: "8px 12px", display: "flex", alignItems: "center" }}>
              <img src={LOGO_SRC} alt="Rotary Bangalore Indiranagar" style={{ height: 34, display: "block" }} />
            </div>
            <div style={{ fontSize: 12, color: COLORS.gold, fontWeight: 700, letterSpacing: ".06em" }}>
              PROJECT REPOSITORY · SERVICE ABOVE SELF
            </div>
          </div>
          <RoleBar role={role} setRole={setRole} director={director} setDirector={setDirector} />
        </div>
      </div>

      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "26px 20px 60px" }}>
        {/* Filters + Add button */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12, marginBottom: 20 }}>
          <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
            <Filter size={15} color={COLORS.inkSoft} />
            <FilterSelect value={filterYear} onChange={(v) => { setFilterYear(v); setFilterMonth("All"); }}
              options={["All", ...years]} />
            <FilterSelect value={filterMonth} onChange={setFilterMonth}
              options={["All", ...monthsAvailable]} />
            <FilterSelect value={filterAvenue} onChange={setFilterAvenue}
              options={["All", ...AVENUES]} />
          </div>
          {canAdd && (
            <button onClick={openAdd} style={{
              display: "flex", alignItems: "center", gap: 8, padding: "10px 18px",
              borderRadius: 999, border: "none", background: COLORS.gold, color: COLORS.blueDeep,
              fontWeight: 700, fontSize: 13, cursor: "pointer", boxShadow: "0 6px 16px rgba(245,166,35,.35)",
            }}>
              <Plus size={16} /> Add Project
            </button>
          )}
        </div>

        {/* Stats */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 14, marginBottom: 22 }}>
          <BigStat icon={LayoutGrid} label="Total Projects" value={totals.count} />
          <BigStat icon={Clock} label="Volunteer Hours" value={totals.hours.toLocaleString("en-IN")} />
          <BigStat icon={IndianRupee} label="Cash Contribution" value={money(totals.cash)} />
          <BigStat icon={Gift} label="In-Kind Contribution" value={money(totals.kind)} />
        </div>

        {/* Charts */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 30 }}>
          <ChartCard title="Projects by Avenue">
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={avenueChartData}>
                <CartesianGrid strokeDasharray="3 3" stroke={COLORS.line} />
                <XAxis dataKey="avenue" tick={{ fontSize: 10.5, fill: COLORS.inkSoft }} />
                <YAxis allowDecimals={false} tick={{ fontSize: 10.5, fill: COLORS.inkSoft }} />
                <Tooltip />
                <Bar dataKey="projects" radius={[6, 6, 0, 0]}>
                  {avenueChartData.map((d, i) => <Cell key={i} fill={AVENUE_COLORS[AVENUES[i]]} />)}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </ChartCard>
          <ChartCard title={`Monthly Contribution — ${filterYear}`}>
            <ResponsiveContainer width="100%" height={220}>
              <LineChart data={monthChartData}>
                <CartesianGrid strokeDasharray="3 3" stroke={COLORS.line} />
                <XAxis dataKey="month" tick={{ fontSize: 10.5, fill: COLORS.inkSoft }} />
                <YAxis tick={{ fontSize: 10.5, fill: COLORS.inkSoft }} />
                <Tooltip />
                <Legend wrapperStyle={{ fontSize: 11 }} />
                <Line type="monotone" dataKey="Cash" stroke={COLORS.blue} strokeWidth={2.5} dot={false} />
                <Line type="monotone" dataKey="In Kind" stroke={COLORS.gold} strokeWidth={2.5} dot={false} />
              </LineChart>
            </ResponsiveContainer>
          </ChartCard>
        </div>

        {/* Project grid */}
        <h3 style={{ fontFamily: "Lora, serif", fontSize: 18, color: COLORS.blueDeep, marginBottom: 14 }}>
          Projects {filtered.length ? `(${filtered.length})` : ""}
        </h3>

        {loading ? (
          <p style={{ color: COLORS.inkSoft, fontSize: 13 }}>Loading repository…</p>
        ) : filtered.length === 0 ? (
          <div style={{ background: COLORS.white, border: `1px dashed ${COLORS.line}`, borderRadius: 14, padding: 40, textAlign: "center", color: COLORS.inkSoft, fontSize: 13.5 }}>
            No projects match these filters yet. {canAdd ? "Add the first one for this selection." : ""}
          </div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 14 }}>
            {filtered.map((p) => (
              <ProjectCard key={p.id} p={p}
                canManage={role === "admin" && canManage(p)}
                onOpen={setViewing} onEdit={openEdit}
                onDelete={(pp) => setConfirmDelete(pp)} />
            ))}
          </div>
        )}
      </div>

      {showForm && (
        <ProjectForm
          role={role}
          lockedAvenue={role === "director" ? director : null}
          initial={editing ? editing : (role === "director" ? { id: uid(), year: CURRENT_YEAR, startDate: "", endDate: "", startTime: "", endTime: "", name: "", avenue: director, volunteerHours: "", contributionCash: "", contributionKind: "", description: "", media: { images: [], files: [], music: [], videoLinks: [] } } : null)}
          onCancel={() => { setShowForm(false); setEditing(null); }}
          onSave={handleSave}
        />
      )}

      {viewing && <ProjectDetail project={viewing} onClose={() => setViewing(null)} />}

      {confirmDelete && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(8,42,80,.55)", zIndex: 60, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ background: COLORS.white, borderRadius: 14, padding: 24, maxWidth: 360 }}>
            <h4 style={{ fontFamily: "Lora, serif", color: COLORS.blueDeep, marginTop: 0 }}>Delete this project?</h4>
            <p style={{ fontSize: 13, color: COLORS.inkSoft, fontFamily: "Inter, sans-serif" }}>
              "{confirmDelete.name}" will be permanently removed from the {confirmDelete.year} repository.
            </p>
            <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 16 }}>
              <button onClick={() => setConfirmDelete(null)} style={{ padding: "8px 16px", borderRadius: 999, border: `1px solid ${COLORS.line}`, background: "white", cursor: "pointer", fontFamily: "Inter, sans-serif", fontSize: 12.5 }}>Cancel</button>
              <button onClick={() => handleDelete(confirmDelete)} style={{ padding: "8px 16px", borderRadius: 999, border: "none", background: COLORS.cranberry, color: "white", cursor: "pointer", fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: 700 }}>Delete</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function FilterSelect({ value, onChange, options }) {
  return (
    <div style={{ position: "relative" }}>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        style={{
          appearance: "none", padding: "8px 30px 8px 12px", borderRadius: 999,
          border: `1px solid ${COLORS.line}`, background: COLORS.white, color: COLORS.ink,
          fontFamily: "Inter, sans-serif", fontSize: 12.5, cursor: "pointer",
        }}
      >
        {options.map((o) => <option key={o} value={o}>{o}</option>)}
      </select>
      <ChevronDown size={13} style={{ position: "absolute", right: 10, top: 9, pointerEvents: "none", color: COLORS.inkSoft }} />
    </div>
  );
}

function BigStat({ icon: Icon, label, value }) {
  return (
    <div style={{ background: COLORS.white, border: `1px solid ${COLORS.line}`, borderRadius: 14, padding: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
        <div style={{ background: COLORS.goldSoft, borderRadius: 8, padding: 6 }}>
          <Icon size={15} color={COLORS.gold} />
        </div>
        <span style={{ fontSize: 11, color: COLORS.inkSoft, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".03em" }}>{label}</span>
      </div>
      <div style={{ fontFamily: "Lora, serif", fontSize: 24, fontWeight: 700, color: COLORS.blueDeep }}>{value}</div>
    </div>
  );
}

function ChartCard({ title, children }) {
  return (
    <div style={{ background: COLORS.white, border: `1px solid ${COLORS.line}`, borderRadius: 14, padding: 16 }}>
      <h4 style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: 700, color: COLORS.inkSoft, textTransform: "uppercase", letterSpacing: ".03em", margin: "0 0 8px" }}>{title}</h4>
      {children}
    </div>
  );
}
